er.source:
erDiagram
  OWNER ||--o{ PET : owns
  PET ||--o{ APPOINTMENT : has
  VET ||--o{ APPOINTMENT : attends
  APPOINTMENT ||--|| INVOICE : billed_by
  OWNER {
    int id PK
    string name
    string phone
  }
  PET {
    int id PK
    int owner_id FK
    string name
    string species
  }
  VET {
    int id PK
    string name
    string license_no
  }
  APPOINTMENT {
    int id PK
    int pet_id FK
    int vet_id FK
    datetime starts_at
  }
  INVOICE {
    int id PK
    int appointment_id FK
    int amount_cents
  }
